import json
from collections import deque

def load_edges(path):
    with open(path) as f:
        return json.load(f)  # list of {"from": "...", "to": "..."}

def build_graph(edge_lists):
    graph = {}
    for edges in edge_lists:
        for e in edges:
            graph.setdefault(e["from"], set()).add(e["to"])
    return graph

def blast_radius(graph, start):
    visited = {start}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, ()):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    visited.discard(start)
    return visited

if __name__ == "__main__":
    documented = load_edges("documented_edges.json")
    discovered = load_edges("discovered_edges.json")
    graph = build_graph([documented, discovered])

    radius = blast_radius(graph, "checkout-db")
    print(f"Blast radius of checkout-db failure: {len(radius)} downstream services")
    for svc in sorted(radius):
        print(f"  - {svc}")

