#!/usr/bin/env python3
"""automated_failover.py — runbook-as-code, not a wiki page."""
import subprocess, sys, time, os, requests

SIGNALS = {
    "synthetic_check": "https://primary.example.com/healthz",
    "lb_target_health": "https://primary.example.com/_internal/lb-health",
}
FAILURE_THRESHOLD = 3          # consecutive failed checks across ALL signals
CHECK_INTERVAL_SEC = 15
KILL_SWITCH_FILE = "/etc/dr/FAILOVER_DISABLED"

def signal_failed(url, timeout=5):
    try:
        r = requests.get(url, timeout=timeout)
        return r.status_code >= 500
    except requests.RequestException:
        return True

def all_signals_agree_failed():
    # Require EVERY independent signal to fail, not just one, to avoid flapping
    return all(signal_failed(url) for url in SIGNALS.values())

def kill_switch_engaged():
    return os.path.exists(KILL_SWITCH_FILE)

def execute_failover():
    print("ALL signals confirm primary is down. Executing failover (idempotent).")
    subprocess.run(["./promote-secondary-region.sh"], check=True)  # tested, idempotent

def main():
    consecutive_failures = 0
    while True:
        if kill_switch_engaged():
            print("Kill switch engaged — failover automation disabled. Exiting.")
            sys.exit(0)
        if all_signals_agree_failed():
            consecutive_failures += 1
        else:
            consecutive_failures = 0
        if consecutive_failures >= FAILURE_THRESHOLD:
            execute_failover()
            sys.exit(0)
        time.sleep(CHECK_INTERVAL_SEC)

if __name__ == "__main__":
    main()

