# check-tag-compliance.ps1 — safe for unattended (Azure Automation) execution
$requiredTags = @("CostCenter", "Environment")
$allResources = Get-AzResource
$nonCompliant = @()
$errors = 0

foreach ($resource in $allResources) {
    try {
        $tags = $resource.Tags
        foreach ($key in $requiredTags) {
            # The defensive check that must come BEFORE .ContainsKey():
            # $tags can be $null for a resource with zero tags, and calling
            # .ContainsKey() on $null throws — "-not $tags" short-circuits first.
            if (-not $tags -or -not $tags.ContainsKey($key)) {
                $nonCompliant += [PSCustomObject]@{
                    Name         = $resource.Name
                    ResourceType = $resource.ResourceType
                    MissingTag   = $key
                }
            }
        }
    }
    catch {
        $errors++
        Write-Error "Failed checking resource $($resource.Name): $_"
        continue   # one bad resource must not abort the whole weekly sweep
    }
}

$nonCompliant | Export-Csv -Path "tag-compliance-$(Get-Date -Format yyyyMMdd).csv" -NoTypeInformation
Write-Output "Compliance sweep complete: $($nonCompliant.Count) violations, $errors resource(s) errored."

